  "case_id": "case-economics-bump-gdp-ranking-top15-decades",
  "language": "en",
  "style": {
    "theme": "editorial",
    "audience": "general public",
    "tone": "bold, narrative-driven, polished"
  },
  "goal": [
    {
      "id": "bump-encoding-mapping",
      "insight": "Encode each country as a line across six decade columns (1970, 1980, 1990, 2000, 2010, 2025), with vertical position representing GDP rank (1 at top, 15 at bottom), and use distinct color and thickness to differentiate highlighted countries from the rest"
    },
    {
      "id": "china-rise-highlight",
      "insight": "Visually highlight China's trajectory as it climbs from rank 9 in 1970 to rank 2 by 2025, using a bold contrasting color and thicker line so the steep upward movement is the most prominent path on the chart"
    },
    {
      "id": "japan-decline-emphasis",
      "insight": "Emphasize Japan's downward trajectory from rank 2 in the 1990s to rank 4 by 2025, using a distinct secondary highlight color to draw attention to the crossing paths with rising economies"
    },
    {
      "id": "india-emergence-pattern",
      "insight": "Show India's entry into the top 5 by 2025 with a third highlight color, making its late-stage surge from the lower ranks visually distinct against the more stable trajectories of established economies"
    },
    {
      "id": "rank-stability-vs-volatility",
      "insight": "Contrast the relatively stable ranking lines of the US (consistently rank 1) and major European economies against the dramatic crossing and shifting lines of Asian economies to emphasize regional dynamism"
    }
  ]
}

