<body>
<div class="page">

  <div class="header">
    <div class="header-eyebrow">Nominal GDP Rankings &nbsp;·&nbsp; 1970 – 2025</div>
    <h1>The Rise of Asia:<br><em>China</em> Reshapes the World Economy</h1>
    <p class="header-sub">How the GDP rankings of the top 15 economies shifted over five decades — from Western dominance to an emerging Asian order.</p>
  </div>

  <div class="chart-wrap">
    <svg id="bump-chart" viewBox="0 0 1020 620" xmlns="http://www.w3.org/2000/svg">
      <!-- Rendered by JS below -->
    </svg>

    <div class="legend">
      <div class="legend-item">
        <div class="legend-line" style="background: #c2410c; height:4px;"></div>
        <span class="legend-label">China</span>
        <span class="legend-sub">rank 9→2 (1970–2025)</span>
      </div>
      <div class="legend-item">
        <div class="legend-line" style="background: #0369a1; height:4px;"></div>
        <span class="legend-label">Japan</span>
        <span class="legend-sub">rank 3→4, peaked at 2</span>
      </div>
      <div class="legend-item">
        <div class="legend-line" style="background: #059669; height:4px;"></div>
        <span class="legend-label">India</span>
        <span class="legend-sub">rank 13→5 (1970–2025)</span>
      </div>
      <div class="legend-item">
        <div class="legend-line" style="background: #1e3a5f; height:3px;"></div>
        <span class="legend-label">United States</span>
        <span class="legend-sub">consistently rank 1</span>
      </div>
      <div class="legend-item">
        <div class="legend-line" style="background: rgba(120,100,80,0.45); height:2px;"></div>
        <span class="legend-label">Other economies</span>
        <span class="legend-sub">Germany, France, UK, Italy, etc.</span>
      </div>
    </div>

    <p class="caption">
      Source: World Bank, IMF. Rankings based on nominal GDP in current USD. 2025 figures are IMF/World Bank estimates. Russia pre-1991 approximated from SFSR share of Soviet GDP.
    </p>
  </div>

</div>

<script>
(function() {
  const years = [1970, 1980, 1990, 2000, 2010, 2025];
  const ranks = 15;

  const data = [
    { country: "United States",  values: [1,1,1,1,1,1],    type: "us" },
    { country: "Japan",          values: [3,2,2,2,3,4],    type: "japan" },
    { country: "Germany",        values: [2,3,3,3,4,3],    type: "other" },
    { country: "France",         values: [4,4,4,5,5,7],    type: "other" },
    { country: "United Kingdom", values: [5,5,6,4,6,6],    type: "other" },
    { country: "Italy",          values: [6,6,5,6,7,9],    type: "other" },
    { country: "Canada",         values: [7,7,7,7,9,10],   type: "other" },
    { country: "China",          values: [9,10,10,6,2,2],  type: "china" },
    { country: "Brazil",         values: [8,8,9,9,8,8],    type: "other" },
    { country: "India",          values: [13,13,13,12,10,5], type: "india" },
    { country: "Australia",      values: [10,11,11,11,13,13], type: "other" },
    { country: "South Korea",    values: [15,15,15,13,14,12], type: "other" },
    { country: "Mexico",         values: [12,12,12,10,11,14], type: "other" },
    { country: "Spain",          values: [11,9,8,8,12,15], type: "other" },
    { country: "Russia",         values: [14,14,14,14,15,11], type: "other" },
  ];

  const colors = {
    china: "#c2410c",
    japan: "#0369a1",
    india: "#059669",
    us:    "#1e3a5f",
    other: "rgba(150,125,95,0.32)"
  };

  const labelColors = {
    china: "#c2410c",
    japan: "#0369a1",
    india: "#059669",
    us:    "#1e3a5f",
    other: "#9e8c7a"
  };

  const strokeWidths = {
    china: 4.5,
    japan: 3.5,
    india: 3.5,
    us:    3,
    other: 1.5
  };

  const svg = document.getElementById("bump-chart");
  const W = 1020, H = 620;
  const marginLeft = 108, marginRight = 130, marginTop = 56, marginBottom = 30;
  const chartW = W - marginLeft - marginRight;
  const chartH = H - marginTop - marginBottom;

  function xPos(i) {
    return marginLeft + (i / (years.length - 1)) * chartW;
  }
  function yPos(rank) {
    return marginTop + ((rank - 1) / (ranks - 1)) * chartH;
  }

  function makePath(values) {
    let d = "";
    for (let i = 0; i < values.length; i++) {
      const x = xPos(i);
      const y = yPos(values[i]);
      if (i === 0) {
        d += `M ${x} ${y}`;
      } else {
        const px = xPos(i - 1);
        const py = yPos(values[i - 1]);
        const cx = (px + x) / 2;
        d += ` C ${cx} ${py}, ${cx} ${y}, ${x} ${y}`;
      }
    }
    return d;
  }

  function svgEl(tag, attrs) {
    const el = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, v);
    return el;
  }

  function svgText(text, attrs) {
    const el = svgEl("text", attrs);
    el.textContent = text;
    return el;
  }

  // Background subtle grid lines (horizontal rank lines)
  const gridG = svgEl("g", { "class": "grid" });
  for (let r = 1; r <= 15; r++) {
    const y = yPos(r);
    const line = svgEl("line", {
      x1: marginLeft - 8, y1: y,
      x2: W - marginRight + 8, y2: y,
      stroke: "rgba(0,0,0,0.045)", "stroke-width": "1",
      "stroke-dasharray": "3 5"
    });
    gridG.appendChild(line);
  }
  svg.appendChild(gridG);

  // Year columns (vertical guides)
  const colG = svgEl("g", { "class": "cols" });
  years.forEach((yr, i) => {
    const x = xPos(i);
    const line = svgEl("line", {
      x1: x, y1: marginTop - 20,
      x2: x, y2: H - marginBottom + 8,
      stroke: "rgba(0,0,0,0.06)", "stroke-width": "1"
    });
    colG.appendChild(line);
    // Year label
    const lbl = svgText(String(yr), {
      x: x, y: marginTop - 26,
      "text-anchor": "middle",
      "font-family": "'JetBrains Mono', monospace",
      "font-size": "13",
      "font-weight": "600",
      fill: "#6b5c4a",
      "letter-spacing": "0.04em"
    });
    colG.appendChild(lbl);
  });
  svg.appendChild(colG);

  // Rank axis labels (left)
  const rankG = svgEl("g", { "class": "ranks" });
  for (let r = 1; r <= 15; r++) {
    const y = yPos(r);
    const lbl = svgText(`${r}`, {
      x: marginLeft - 18,
      y: y + 4.5,
      "text-anchor": "end",
      "font-family": "'JetBrains Mono', monospace",
      "font-size": "12",
      fill: r === 1 ? "#1e3a5f" : "#b0a090",
      "font-weight": r === 1 ? "600" : "400"
    });
    rankG.appendChild(lbl);
  }
  // Axis title
  const axisTitle = svgText("← Rank (1 = largest GDP)", {
    x: marginLeft - 20,
    y: marginTop - 40,
    "text-anchor": "start",
    "font-family": "'Plus Jakarta Sans', sans-serif",
    "font-size": "11",
    fill: "#9e8c7a",
    "font-weight": "500",
    "letter-spacing": "0.02em"
  });
  rankG.appendChild(axisTitle);
  svg.appendChild(rankG);

  // Draw lines — others first (behind), then highlights
  const others = data.filter(d => d.type === "other");
  const highlights = data.filter(d => d.type !== "other");

  const linesG = svgEl("g", { "class": "lines" });

  // Others
  others.forEach(d => {
    const path = svgEl("path", {
      d: makePath(d.values),
      fill: "none",
      stroke: colors[d.type],
      "stroke-width": strokeWidths[d.type],
      "stroke-linecap": "round",
      "stroke-linejoin": "round"
    });
    linesG.appendChild(path);
  });

  // Highlights (drawn on top)
  // Draw glow/halo for highlighted lines
  const glowTypes = ["china", "japan", "india"];
  glowTypes.forEach(type => {
    const d = data.find(e => e.type === type);
    if (!d) return;
    // Halo
    const haloPath = svgEl("path", {
      d: makePath(d.values),
      fill: "none",
      stroke: colors[type],
      "stroke-width": strokeWidths[type] + 8,
      "stroke-linecap": "round",
      opacity: "0.08"
    });
    linesG.appendChild(haloPath);
    // Main line
    const mainPath = svgEl("path", {
      d: makePath(d.values),
      fill: "none",
      stroke: colors[type],
      "stroke-width": strokeWidths[type],
      "stroke-linecap": "round",
      "stroke-linejoin": "round"
    });
    linesG.appendChild(mainPath);
  });

  // US line (bold, dark)
  const usData = data.find(d => d.type === "us");
  const usHalo = svgEl("path", {
    d: makePath(usData.values),
    fill: "none",
    stroke: colors.us,
    "stroke-width": strokeWidths.us + 6,
    "stroke-linecap": "round",
    opacity: "0.07"
  });
  linesG.appendChild(usHalo);
  const usPath = svgEl("path", {
    d: makePath(usData.values),
    fill: "none",
    stroke: colors.us,
    "stroke-width": strokeWidths.us,
    "stroke-linecap": "round",
    "stroke-dasharray": "6 3"
  });
  linesG.appendChild(usPath);

  svg.appendChild(linesG);

  // Dots and labels at each year for highlighted countries + US
  const dotsG = svgEl("g", { "class": "dots" });
  const labelsG = svgEl("g", { "class": "labels" });

  const labelData = data.filter(d => d.type !== "other");

  // Right-side labels (2025 column)
  // Also add left-side labels (1970 column) for context
  const rightLabelOffsets = {}; // track y to avoid collision
  const leftLabelOffsets = {};

  // Sort by 2025 rank for right labels
  const sortedByRight = [...labelData].sort((a, b) => a.values[5] - b.values[5]);

  sortedByRight.forEach((d, idx) => {
    const lastX = xPos(5);
    const lastY = yPos(d.values[5]);
    const color = colors[d.type];
    const lcolor = labelColors[d.type];

    // Dot at 2025
    const circle = svgEl("circle", {
      cx: lastX, cy: lastY, r: d.type === "other" ? 3 : 5,
      fill: color
    });
    dotsG.appendChild(circle);

    // Right label
    const shortName = d.country === "United States" ? "USA" : d.country;
    const label = svgText(shortName, {
      x: lastX + 14,
      y: lastY + 4.5,
      "font-family": "'Plus Jakarta Sans', sans-serif",
      "font-size": d.type === "other" ? "12" : "13.5",
      "font-weight": d.type === "other" ? "400" : "600",
      fill: lcolor
    });
    labelsG.appendChild(label);

    // Rank badge next to label
    const rankBadge = svgText(`#${d.values[5]}`, {
      x: lastX + 14 + shortName.length * 7.8 + 4,
      y: lastY + 4.5,
      "font-family": "'JetBrains Mono', monospace",
      "font-size": "11",
      fill: lcolor,
      opacity: "0.7"
    });
    labelsG.appendChild(rankBadge);
  });

  // Left labels (1970)
  labelData.forEach(d => {
    const firstX = xPos(0);
    const firstY = yPos(d.values[0]);
    const color = colors[d.type];
    const lcolor = labelColors[d.type];

    // Dot at 1970
    const circle = svgEl("circle", {
      cx: firstX, cy: firstY, r: d.type === "other" ? 3 : 5,
      fill: color
    });
    dotsG.appendChild(circle);

    const shortName = d.country === "United States" ? "USA" : d.country;
    const lbl = svgText(shortName, {
      x: firstX - 14,
      y: firstY + 4.5,
      "text-anchor": "end",
      "font-family": "'Plus Jakarta Sans', sans-serif",
      "font-size": d.type === "other" ? "12" : "13.5",
      "font-weight": d.type === "other" ? "400" : "600",
      fill: lcolor
    });
    labelsG.appendChild(lbl);
  });

  // Also add dots at intermediate years for highlighted lines
  ["china", "japan", "india", "us"].forEach(type => {
    const d = data.find(e => e.type === type);
    if (!d) return;
    d.values.forEach((rank, i) => {
      if (i === 0 || i === 5) return; // already drawn
      const cx = xPos(i);
      const cy = yPos(rank);
      const dot = svgEl("circle", {
        cx, cy, r: type === "other" ? 2.5 : 3.5,
        fill: colors[type],
        opacity: "0.85"
      });
      dotsG.appendChild(dot);
    });
  });

  svg.appendChild(dotsG);
  svg.appendChild(labelsG);

  // Annotation for China's peak movement
  const chinaData = data.find(d => d.type === "china");
  // Annotation arrow at 2010 point
  const annX = xPos(4); // 2010
  const annY = yPos(chinaData.values[4]); // rank 2

  const annG = svgEl("g", { "class": "annotation" });
  // Small callout
  const annotRect = svgEl("rect", {
    x: annX + 12, y: annY - 28,
    width: 170, height: 24,
    rx: 4, fill: "rgba(194,65,12,0.08)",
    stroke: "rgba(194,65,12,0.2)", "stroke-width": "1"
  });
  annG.appendChild(annotRect);
  const annotText = svgText("China surges to #2 by 2010", {
    x: annX + 20, y: annY - 11,
    "font-family": "'Plus Jakarta Sans', sans-serif",
    "font-size": "11.5",
    "font-weight": "600",
    fill: "#c2410c"
  });
  annG.appendChild(annotText);

  // India annotation at 2025
  const indiaData = data.find(d => d.type === "india");
  const indAnnX = xPos(5);
  const indAnnY = yPos(indiaData.values[5]);
  const indRect = svgEl("rect", {
    x: indAnnX - 190, y: indAnnY + 10,
    width: 168, height: 24,
    rx: 4, fill: "rgba(5,150,105,0.08)",
    stroke: "rgba(5,150,105,0.2)", "stroke-width": "1"
  });
  annG.appendChild(indRect);
  const indText = svgText("India enters top 5 by 2025", {
    x: indAnnX - 182, y: indAnnY + 27,
    "font-family": "'Plus Jakarta Sans', sans-serif",
    "font-size": "11.5",
    "font-weight": "600",
    fill: "#059669"
  });
  annG.appendChild(indText);

  svg.appendChild(annG);

  // Chart title inside SVG (top-left)
  const chartLabel = svgText("GDP RANK OVER TIME — TOP 15 ECONOMIES", {
    x: marginLeft, y: 22,
    "font-family": "'JetBrains Mono', monospace",
    "font-size": "10",
    "font-weight": "600",
    fill: "#9e8c7a",
    "letter-spacing": "0.1em"
  });
  svg.appendChild(chartLabel);

})();
</script>
</body>
</html>
